        'host'     => 'smtp.example.com',    // ЗАГЛУШКА → напр. mail.iceberg.spb.ru
        'port'     => 465,                   // 465 для ssl, 587 для tls
        'secure'   => 'ssl',                 // 'ssl' | 'tls' | '' (без шифрования)
        'auth'     => true,
        'username' => 'noreply@iceberg.spb.ru',  // ЗАГЛУШКА
        'password' => 'CHANGE_ME_SMTP_PASSWORD', // ЗАГЛУШКА
